package test;

import org.eclipse.jface.preference.IPreferenceStore;
import org.eclipse.ui.texteditor.ChainedPreferenceStore;
import org.eclipse.ui.internal.editors.text.EditorsPlugin;

public class EditorInitialization {
    protected void initializeEditor() {
        IPreferenceStore[] stores = new IPreferenceStore[] {
                org.eclipse.ui.internal.genericeditor.preferences.GenericEditorPreferenceConstants.getPreferenceStore(),
                EditorsPlugin.getDefault().getPreferenceStore()
        };
        setPreferenceStore(new ChainedPreferenceStore(stores));
    }
    private void setPreferenceStore(IPreferenceStore store) {}
}

